<script setup lang="ts">import {ref} from 'vue';import {post} from '../api/client';import {save} from '../stores/session';import type {User} from '../types/domain';import Notice from '../components/common/Notice.vue';const emit=defineEmits<{login:[User]}>();const email=ref('analyst@hengyuan.demo'),password=ref('Network2026!'),error=ref(''),busy=ref(false);async function login(){busy.value=true;try{const r=await post<{token:string;user:User}>('/auth/login',{email:email.value,password:password.value});save(r.token,r.user);emit('login',r.user)}catch(e){error.value=(e as Error).message}finally{busy.value=false}};</script><template><main class="login"><section class="login-atlas"><span class="atlas-label">HENGYUAN / TRANSFER NETWORKS</span><h1>一条边停用，<br/>网络还能承接多少？</h1><p>把容量、最小割与最短时长分开核查，<br/>让绕行和瓶颈都有可追溯的证据。</p><div class="cover-proofs"><span>01<small>边容量</small></span><span>02<small>流守恒</small></span><span>03<small>可达路径</small></span></div><small>模拟联运规划 / 不连接真实调度服务</small></section><section class="login-form"><span class="eyebrow">衡远联运 · 中转网络韧性推演</span><h2>打开网络图册</h2><p>节点、边、停用方案与复核依据一并保存。</p><form @submit.prevent="login"><label>工作账号<input aria-label="工作账号" v-model="email"/></label><label>密码<input aria-label="密码" type="password" v-model="password"/></label><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">{{busy?'正在验证…':'打开图册　→'}}</button></form><div class="login-accounts"><b>演示账号</b><p>admin / analyst / viewer @hengyuan.demo<br/>统一密码 Network2026!</p></div></section></main></template>
